/* Each nav item on one line, space after it */
nav li {
  margin-right: 0.5em;
  display: inline-block;
}

/* Link states, in this order: :link, :visited, :hover, :active */
a:link {
  color: #13305c;
}
a:visited {
  color: #551a8b;
}
a:hover, a:focus {
  background-color: #fff3c4;
}
a:active {
  color: #8a1c55;
}

/* Nav links: white on navy; maroon under the mouse or keyboard */
nav a:link, nav a:visited {
  color: #ffffff;
  background-color: #13305c;
  padding: 0.25em 0.75em;
  text-decoration: none;
}
nav a:hover, nav a:focus {
  background-color: #8a1c55;
}

/* Class selector: every element with class="badge" */
.badge {
  background-image: linear-gradient(#fff3c4, #ffe08a);
  font-size: 12px;
  text-transform: uppercase;
  padding: 0.25em 0.5em;
  border: 1px solid #b45309;
}

/* Lists: square bullets inside the box; Roman numbers */
.skills {
  list-style-type: square;
  list-style-position: inside;
  padding-left: 0;
}
.next {
  list-style-type: upper-roman;
}

/* Element selector: every paragraph */
p {
  color: #333333;
}

/* Element selector: every label */
label {
  font-weight: bold;
  font-size: 1.1em;
}

/* A comma lists several selectors: every form box 300px wide, padding and border included */
input, select, textarea {
  box-sizing: border-box;
  width: 300px;
  padding: 4px;
  border: 1px solid #555555;
}

/* Element selector: small print, faded with opacity */
small {
  opacity: 0.75;
}

/* ID selector: only the element with id="form-note" */
#form-note {
  color: #9b1c1c;
  font-weight: bold;
  font-style: italic;
}

/* The framed contact page: solid border, space above */
iframe {
  border: 2px solid #13305c;
  margin-top: 0.5em;
}

